import { Component, Input, Output, EventEmitter, OnChanges } from '@angular/core';
import { MeasurementType, ArithOperation, CalculateRequest, UNITS } from '../../../../core/models/measurement.models';

@Component({
  selector: 'app-arithmetic-panel',
  templateUrl: './arithmetic-panel.component.html'
})
export class ArithmeticPanelComponent implements OnChanges {

  @Input() currentType: MeasurementType = 'Length';
  @Input() isLoading = false;
  @Output() execute = new EventEmitter<CalculateRequest>();

  units: string[] = [];
  value1 = 1;
  value2 = 1;
  unit1 = '';
  unit2 = '';
  operation: ArithOperation = 'Add';
  targetUnit = '';

  readonly operations: ArithOperation[] = ['Add', 'Subtract', 'Divide'];

  readonly opBadges: Record<ArithOperation, string> = {
    Add: '+', Subtract: '−', Divide: '÷'
  };

  // Only show "Result in" target unit selector when: Add + Length
  get showTargetUnit(): boolean {
    return this.operation === 'Add' && this.currentType === 'Length';
  }

  ngOnChanges(): void {
    this.units = UNITS[this.currentType];
    this.unit1 = this.units[0];
    this.unit2 = this.units[1] || this.units[0];
    this.targetUnit = this.units[0];
  }

  onCalculate(): void {
    const req: CalculateRequest = {
      category:  this.currentType,
      value1:    this.value1,
      unit1:     this.unit1,
      value2:    this.value2,
      unit2:     this.unit2,
      operation: this.operation
    };
    if (this.showTargetUnit) req.targetUnit = this.targetUnit;
    this.execute.emit(req);
  }
}
<div class="input-panel active">
  <div class="arith-row">

    <div class="input-group">
      <div class="section-label">Value 1</div>
      <input class="value-input" type="number" [(ngModel)]="value1" step="any"/>
      <select class="unit-select" [(ngModel)]="unit1">
        <option *ngFor="let u of units" [value]="u">{{ u }}</option>
      </select>
    </div>

    <div style="display:flex;flex-direction:column;align-items:center;gap:6px;padding-bottom:10px">
      <div class="op-badge">{{ opBadges[operation] }}</div>
    </div>

    <div class="input-group">
      <div class="section-label">Value 2</div>
      <input class="value-input" type="number" [(ngModel)]="value2" step="any"/>
      <select class="unit-select" [(ngModel)]="unit2">
        <option *ngFor="let u of units" [value]="u">{{ u }}</option>
      </select>
    </div>

  </div>

  <!-- Operation selector + optional target unit -->
  <div class="arith-target">
    <label>Operation:</label>
    <select class="unit-select" [(ngModel)]="operation" style="width:auto;min-width:140px">
      <option *ngFor="let op of operations" [value]="op">{{ op }}</option>
    </select>

    <ng-container *ngIf="showTargetUnit">
      <label style="margin-left:12px">Result in:</label>
      <select class="unit-select" [(ngModel)]="targetUnit" style="width:auto;min-width:140px">
        <option *ngFor="let u of units" [value]="u">{{ u }}</option>
      </select>
    </ng-container>
  </div>

  <div class="execute-row" style="margin-top:20px">
    <button class="btn-execute" [class.loading]="isLoading" (click)="onCalculate()">
      <div class="spinner"></div>
      <span class="btn-text">{{ isLoading ? 'Calculating...' : 'Calculate' }}</span>
    </button>
  </div>
</div>
